## Matching on Multiple Values at Once

You can match on a **tuple** — multiple values grouped together — and destructure all of them simultaneously.

### Tuple Matching Basics

```xiom
fn main() -> Int {
  let pair = (Some(10), Ok("hello"));

  match pair {
    (Some(x), Ok(y)) => io.println("Both present: " + string.int_to_str(x) + " and " + y),
    (None, Ok(y)) => io.println("First missing, second: " + y),
    (Some(x), Err(e)) => io.println("First: " + string.int_to_str(x) + ", second error: " + e),
    (None, Err(e)) => io.println("Both failed: " + e),
  };
  return 0;
}
```

### Real-World: Coordinate Check

```xiom
fn is_origin(point: (Int, Int)) -> Str {
  return match point {
    (0, 0) => "At the origin",
    (0, y) => "On the Y-axis at " + string.int_to_str(y),
    (x, 0) => "On the X-axis at " + string.int_to_str(x),
    (x, y) => "At (" + string.int_to_str(x) + ", " + string.int_to_str(y) + ")",
  };
}

fn main() -> Int {
  io.println(is_origin((0, 0)));    // At the origin
  io.println(is_origin((0, 5)));    // On the Y-axis at 5
  io.println(is_origin((3, 0)));    // On the X-axis at 3
  io.println(is_origin((4, 7)));    // At (4, 7)
  return 0;
}
```

### Nested Option and Result

```xiom
fn check_data(maybe_num: Option[Int], maybe_text: Result[Str, Str]) -> Str {
  return match (maybe_num, maybe_text) {
    (Some(n), Ok(t)) => {
      return "Got number " + string.int_to_str(n) + " and text '" + t + "'";
    },
    (Some(n), Err(e)) => {
      return "Number is " + string.int_to_str(n) + " but text failed: " + e;
    },
    (None, Ok(t)) => {
      return "No number but text is '" + t + "'";
    },
    (None, Err(e)) => {
      return "Nothing worked: " + e;
    },
  };
}

fn main() -> Int {
  io.println(check_data(Some(42), Ok("success")));
  io.println(check_data(Some(7), Err("bad text")));
  io.println(check_data(None, Ok("data")));
  io.println(check_data(None, Err("all broken")));
  return 0;
}
```

### Triple Matching

```xiom
fn compare_three(a: Int, b: Int, c: Int) -> Str {
  return match (a, b, c) {
    (x, y, z) if x == y && y == z => "All three equal: " + string.int_to_str(x),
    (x, y, _) if x == y => "First two equal: " + string.int_to_str(x),
    (_, y, z) if y == z => "Last two equal: " + string.int_to_str(y),
    (x, _, _) => "Largest is first: " + string.int_to_str(x),
  };
}
```

