fn main() -> Int {
  let data = (Some(5), Ok("ready"));
  match data {
    (Some(n), Ok(msg)) => io.println("Value: " + string.int_to_str(n) + ", Message: " + msg),
    (Some(n), Err(e)) => io.println("Value: " + string.int_to_str(n) + ", Error: " + e),
    (None, Ok(msg)) => io.println("No value, Message: " + msg),
    (None, Err(e)) => io.println("No value, Error: " + e),
  };

  let nums = (5, -3, 8);
  match nums {
    (a, b, c) => {
      if a > 0 && b > 0 && c > 0 { io.println("All positive"); }
      else if a < 0 && b < 0 && c < 0 { io.println("All negative"); }
      else { io.println("Mixed"); }
    },
  };
  return 0;
}
